import os

class SegmentTree:
    def __init__(self, arr):
        self.n = len(arr)
        self.sum_tree = [0] * (4 * self.n)
        self.max_tree = [0] * (4 * self.n)
        self.lazy = [0] * (4 * self.n)
        self._build(arr, 0, 0, self.n - 1)

    def _build(self, node, left, right):
        if left == right:
            self.sum_tree[node] = self.max_tree[node] = self.arr[left]
        else:
            mid = (left + right) // 2
            self._build(2 * node + 1, left, mid)
            self._build(2 * node + 2, mid + 1, right)
            self.sum_tree[node] = self.sum_tree[2 * node + 1] + self.sum_tree[2 * node + 2]
            self.max_tree[node] = max(self.max_tree[2 * node + 1], self.max_tree[2 * node + 2])

    def _apply(self, node, left, right, val):
        self.sum_tree[node] += val * (right - left + 1)
        self.max_tree[node] += val
        self.lazy[node] += val

    def _push(self, node, left, right):
        mid = (left + right) // 2
        if self.lazy[node] != 0:
            self._apply(2 * node + 1, left, mid, self.lazy[node])
            self._apply(2 * node + 2, mid + 1, right, self.lazy[node])
            self.lazy[node] = 0

    def range_add(self, node, left, right, l, r, val):
        if l > right or r < left:
            return
        if l <= left and right <= r:
            self._apply(node, left, right, val)
            return
        self._push(node, left, right)
        mid = (left + right) // 2
        self.range_add(2 * node + 1, left, mid, l, r, val)
        self.range_add(2 * node + 2, mid + 1, right, l, r, val)
        self.sum_tree[node] = self.sum_tree[2 * node + 1] + self.sum_tree[2 * node + 2]
        self.max_tree[node] = max(self.max_tree[2 * node + 1], self.max_tree[2 * node + 2])

    def query_max(self, node, left, right, l, r):
        if l > right or r < left:
            return float('-inf')
        if l <= left and right <= r:
            return self.max_tree[node]
        self._push(node, left, right)
        mid = (left + right) // 2
        return max(
            self.query_max(2 * node + 1, left, mid, l, r),
            self.query_max(2 * node + 2, mid + 1, right, l, r)
        )

    def __init__(self, arr):
        self.arr = arr

