def solution(grid_str):
    """
    Solves the grid graph coloring problem.
    Input: grid_str - string with dimensions and coloring
    Output: colored grid or "0" if impossible
    """
    import re  # Used for parsing if needed

    # Parse input
    lines = grid_str.strip().split('\n')
    if len(lines) < 1:
        return '0'

    n, m = map(int, lines[0].split())

    if len(lines) != n + 1:
        return '0'

    grid = [list(line) for line in lines[1:n+1]]

    # Check for conflicts in input: connected vertices with same color
    def check_conflicts(grid, n, m):
        for i in range(n):
            for j in range(m):
                if grid[i][j] != '0':
                    # Check all 8 neighbors
                    for di in range(-1, 2):
                        for dj in range(-1, 2):
                            ni, nj = i + di, j + dj
                            if di == 0 and dj == 0:
                                continue
                            if 0 <= ni < n and 0 <= nj < m:
                                if grid[ni][nj] != '0' and grid[i][j] == grid[ni][nj]:
                                    return True
        return False

    # For strong grid graphs with 4 colors, greedy approach works
    # Each cell needs to differ from up to 8 neighbors
    # Colors available: 1, 2, 3, 4

    for i in range(n):
        for j in range(m):
            if grid[i][j] == '0':
                used_colors = set()
                for di in range(-1, 2):
                    for dj in range(-1, 2):
                        ni, nj = i + di, j + dj
                        if ni != i or nj != j:
                            if 0 <= ni < n and 0 <= nj < m:
                                c = grid[ni][nj]
                                if c != '0':
                                    used_colors.add(int(c))

                # Find valid color
                for color in [1, 2, 3, 4]:
                    if color not in used_colors:
                        grid[i][j] = str(color)
                        break
                else:
                    # Cannot color - should not happen with proper graph
                    return '0'

    # Verify no conflicts in result
    if check_conflicts(grid, n, m):
        return '0' or '0'

    return '\n'.join(''.join(row) for row in grid)
