    import sys
    import os

    def get_divisors(n):
        divs = []
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                divs.append(i)
                if i != n // i:
                    divs.append(n // i)
        divs.append(n)
        return sorted(divs)

    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    def lcm(a, b):
        return abs(a * b) // gcd(a, b)

    lines = input_str.strip().split('\n')
    t = int(lines[0])

    results = []
    for i in range(1, t + 1):
        n = int(lines[i])
        divs = get_divisors(n)

        if not divs:
            continue

        # Sort divisors by value first
        arr = sorted(divs)

        # Try to rearrange to minimize adjacent coprime pairs
        # Strategy: group by prime factors where possible

        # For divisors that can form valid chains (share a prime factor), keep them together
        # n itself is divisible by all prime factors of n

