    adj = [[] for _ in range(n + 1)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # Check if graph has bridges using Tarjan's algorithm
    dfn = {}
    low = {}
    bridges = False
    has_bridges = False

    time_counter = [0]
    visited = set()

    def find_bridges(u, parent):
        nonlocal has_bridges, bridges
        visited.add(u)
        dfn[u] = time_counter[0]
        low[u] = time_counter[0]
        time_counter[0] += 1

        for v in adj[u]:
            if v == parent:
                continue
            if v in dfn:
                # Back edge
                low[u] = min(low[u], dfn[v])
            else:
                # Tree edge
                find_bridges(v, u)
                low[u] = min(low[u], low[v])
                if low[v] > dfn[u]:
                    has_bridges = True

    # Check all nodes (graph is connected per problem statement)
    find_bridges(1, -1)

    # Also check if there are any bridges
    bridges = has_bridges

    # If there are bridges, we cannot make it strongly connected
    if bridges:
        return '0'

    # If no bridges, we can orient edges properly
    # Orient in DFS order: tree edges downstream, back edges upstream
    parent_edge = {}
    visited = {}
    dfs_order = []
    timer = 0

    def dfs_orient(u, p):
        nonlocal timer
        visited[u] = True
        dfs_order.append(u)
        timer += 1

        for v in adj[u]:
            if not visited.get(v, False):
                parent_edge[(u, v)] = (u, v)
                parent_edge[(v, u)] = (v, u)
                dfs_orient(v, u)
            elif v != p and not visited[v]:
                pass

    # Actually the orientation is simpler: DFS tree edges go away from
    # root, and all other edges (to ancestors) can go back

    # Simple orientation: DFS tree edges parent->child
    # Back edges can be child->ancestor
    orientation = {}  # (u,v) -> True if u->v

    def orient(u, p):
        for v in adj[u]:
            if v == p:
                continue
            if v in dfs_orient:
                # Back edge - orient from child to parent
                if v in dfs_order and dfs_order.index(v) < dfs_order.index(u):
                    continue
            else:
                # Tree edge - orient parent to child
                orientation[(u, v)] = True
                orient(v, u)

    dfs_orient = dict()
    dfs_orient[u] = True
