def solution(input_str):
    try:
        lines = input_str.strip().split('\n')
        if len(lines) < 3:
            return "0\n"

        n, m = map(int, lines[0].split())
        s = lines[1]
        t = lines[2]

        result = []

        for i in range(n - m + 1):
            valid = True
            mapping = {}  # c1 -> c2

            for j in range(m):
                c1 = s[i + j]
                c2 = t[j]

                if c1 == c2:
                    continue

                # If c1 already mapped, must map to same c2
                if c1 in mapping:
                    if mapping[c1] != c2:
                        valid = False
                        break
                else:
                    mapping[c1] = c2

            if not valid:
                continue

            # Check bidirectional pairs
            pairs = set()
            for c, target in mapping.items():
                if (target, c) in mapping:
                    pairs.add((c, target))
                else:
                    # If c maps to target but target doesn't map back to c,
                    # this is only valid if c == target (but we only add if c != target)
                    # Actually this is invalid - need bidirectional
                    pass

            # More careful check: for each pair (c1, c2) in mapping,
            # we need c2 to also map to c1
            has_unpaired = False
            for c1, c2 in mapping.items():
                if c2 not in mapping or mapping[c2] != c1:
                    has_unpaired = True
                    break

            if has_unpaired:
                continue

            result.append(i + 1)

        result.sort()
        if not result:
            return "0\n"

        output = str(len(result)) + "\n" + " ".join(map(str, result))
        return output
    except Exception:
        return "0\n"
