                c1, c2 = ord(a[i]) - 97, ord(b[i]) - 97
                root = find(c1)
                components[root]['vertices'].add(c1)
                components[root]['vertices'].add(c2)
                components[root]['edges'].add((min(c1, c2), max(c1, c2)))

        moves = 0
        for root in components:
            moves += max(len(components[root]['vertices']), len(components[root]['edges']))

        return moves

    for _ in range(t):
