    if k == 1:
        return str(n % MOD)

    memo = {}

    def dfs(current, remaining, visited):
        if remaining == 0:
            return 1

        state = (current, remaining, tuple(sorted(visited)))
        if state in memo:
            return memo[state]

        total = 0
        # From current planet, can move to any planet in range [1, current + m]
        for next_planet in range(1, min(n, current + m) + 1):
            if next_planet not in visited:
                new_visited = visited | {next_planet}
                total = (total + dfs(next_planet, remaining - 1, new_visited)) % MOD

        memo[state] = total
        return total

    # Try each possible starting planet
    ans = 0
    for start in range(1, n + 1):
        ans = (ans + dfs(start, k - 1, {start})) % MOD

    return str(ans)
