    Supports add, delete, and query operations for linear functions
    """
    def __init__(self, min_q, max_q):
        self.min_q = min_q
        self.max_q = max_q
        self.n_range = max_q - min_q + 1
        self.size = 1
        while self.size < self.n_range * 4:
            self.size *= 2

        # Each position stores (Line, active_query_id)
