        """Add a line with slope m and intercept c, marked with query_id"""
        line = Line(m, c)
        self._add_line(0, 0, self.size - 1, line, query_id)

    def _add_line(self, node, low, high, line, query_id, idx):
        if low == high:
            if self.lines[node] is None:
                self.lines[node] = line
            elif idx > self.lines[node]._id if hasattr(self.lines[node], '_id') else 0:
                self.lines[node] = line
            return

        mid = (low + high) >> 1
        mid_q = self.min_q + mid

        if self.lines[node] is None:
            self.lines[node] = line
        else:
            existing = self.lines[node]
            # If new line is better at midpoint, swap
            if line.eval(mid_q) > existing.eval(mid_q):
                self.lines[node], existing = line, existing

        self.lines[node] = existing

        # Recurse with the line that's worse at midpoint
        if low == high:
            return

        if low != mid and line.eval(low) > existing.eval(low):
            self._add_line(2 * node + 1, low, mid, line, query_id)
        elif high != mid and line.eval(high) > existing.eval(high):
            self._add_line(2 * node + 2, mid + 1, high, line, query_id)

    def delete(self, q_id):
        """Mark line added at query_id as deleted"""
        for i in range(len(self.lines)):
            if self.lines[i] is not None:
                if hasattr(self.lines[i], '_id') and self.lines[i]._id == q_id:
                    self.lines[i] = None

    def query(self, q):
        """Query max value at point q"""
        best = -float('inf')

        node = 0
        while node < self.size:
            if self.lines[node] is not None:
                val = self.lines[node].eval(q)
                if val > best:
                    best = val
            node = 2 * node + 2
            if node >= self.size:
                break

        return best

    def is_empty(self):
        """Check if any active lines exist"""
        return all(l is None for l in self.lines)


