from collections import defaultdict
import os

class DSU:
    """Union-Find with parity tracking for 2-SAT constraints."""
    def __init__(self, n):
        self.parent = list(range(n))
        self.diff = [0] * n  # parity relative to parent

    def find(self, x):
        if self.parent[x] != x:
            root = self.find(self.parent[x])
            self.diff[x] ^= self.diff[self.parent[x]]
        return self.parent[x]

    def union(self, x, y):
        """Union x and y with constraint that they have different parities."""
        root_x = self.find(x)
        root_y = self.find(y)

        if root_x == root_y:
            # Already connected - check for contradiction
            return self.diff[x] != 1

        # Merge components
        self.parent[root_x] = root_y
        self.diff[root_x] = 1
        return True

    def get_assign(self, x):
        """Get the assignment for x: 0=inside (i), 1=outside (o)"""
        self.find(x)
        return self.diff[x]

def interleaves(a, b, c, d, n):
    """Check if edges (a,b) and (c,d) interleave on the cycle."""
    a %= n
    b %= n
    c %= n
    d %= n

    def in_arc(p, start, end):
        """Check if p is in clockwise arc from start to end (exclusive)."""
        if start < end:
            return start < p < end
        else:
            return p > start or p < end

    # Two edges interleave if exactly one endpoint of second is in the arc of first
    c_in = in_arc(c, a, b)
    d_in = in_arc(d, a, b)
    return c_in != d_in

def solution(input_str):
    """
    Main solution function that processes the input and returns the result.

    The input string contains:
    - Line 1: n m (number of cities and roads to build)
    - Following m lines: pairs of cities for each road
    """
