import math
from collections import deque

def solution(input_str):
    lines = input_str.strip().split('\n')
    idx = 0

    if idx >= len(lines):
        return ""

    n, m = map(int, lines[idx].split())
    idx += 1

    graph = [[] for _ in range(n + 1)]
    for i in range(m):
        if idx >= len(lines):
            break
        a, b, l = map(int, lines[idx].split())
        idx += 1
        graph[a].append((b, l))

    if idx >= len(lines):
        q = 0
    else:
        q = int(lines[idx])
        idx += 1

    # component_gcd[v] stores the gcd of all cycle lengths in the component containing v
    component_gcd = [0] * (n + 1)

    visited = [False] * (n + 1)

    for root in range(1, n + 1):
        if not visited[root]:
            # BFS to find connected component and store distances
            dist = {root: 0}
            queue = deque([root])
            visited[root] = True
            nodes = []

            while queue:
                u = queue.popleft()
                nodes.append(u)
                for v, l in graph[u]:
                    if v not in dist:
                        dist[v] = dist[u] + l
                        visited[v] = True
                        queue.append(v)

            # Compute GCD of all cycle lengths in this component
            g = 0
            for u in nodes:
                for v, l in graph[u]:
                    if v in dist:
                        # This edge creates a cycle with the path to v
                        cycle = dist[u] + l - dist[v]
                        if cycle != 0:
                            if g == 0:
                                g = abs(cycle)
                            else:
                                g = math.gcd(g, abs(cycle))

            # Assign the computed GCD to all nodes in this component
            for node in nodes:
                component_gcd[node] = g

    results = []
    for _ in range(q):
        if idx >= len(lines):
            break
        v, s, t = map(int, lines[idx].split())
        idx += 1

        g = component_gcd[v]

        # If odometer is already 0, no driving needed
        if s == 0:
            results.append("YES")
        else:
            # If no cycles exist in component, can't adjust odometer
            if g == 0:
                results.append("NO")
            else:
                # Check if problem k*g = -s (mod t) has solution
                # This is true iff gcd(g, t) divides s
                if s % math.gcd(g, t) == 0:
                    results.append("YES")
                else:
                    results.append("NO")

    return '\n'.join(results)
