# Solution to be returned by solution function
def solution(input_text):
    """
    Simulate the frog game on a cyclic board.
    """
    lines = input_text.strip().split('\n')
    if not lines:
        return "0\n"

    n, m = map(int, lines[0].split())

    # Store frog state: index -> (pos, a, id)
    frogs = []
    for i in range(n):
        pos, a = map(int, lines[i + 1].split())
        frogs.append({'id': i + 1, 'pos': pos, 'a': a})

    # Track remaining frogs
    remaining = [i for i in range(1, n + 1)]

    # Simulation
    for _ in range(n * n):  # Safety limit
        # Get active frogs (a > 0) in original order
        active = [frogs[i] for i in range(n) 
                  if any(r == i + 1 for r in remaining) and frogs[i]['a'] > 0]
        if not active:
            break

        frog = active[0]
        a = frog['a']

        if a <= 0:
            continue

        # Calculate new position (1-indexed, cyclic)
        new_pos = ((frog['pos'] - 1 + a) % m) + 1

        # Path cells: from pos+1 to new_pos (excluding start, including end)
        path_cells = []
        for j in range(a):
            path_cells.append(((frog['pos'] - 1 + j + 1) % m) + 1)

        # Check which frogs are on path (excluding self)
        knocked = []
        frog_pos = frog['pos']

        for i in range(len(frogs)):
            if frogs[i]['id'] != frog['id']:
                if frogs[i]['pos'] in path_cells:
                    if frogs[i]['id'] in remaining:
                        knocked.append(i)

        # Remove knocked frogs
        for idx in knocked:
            if frogs[idx]['id'] in remaining:
                remaining.append(frogs[idx]['id'])
                frogs[idx]['pos'] = 0

        # Update current frog
        frog['pos'] = new_pos
        frog['a'] -= len(knocked)

    # Collect final frogs
    result_frogs = []
    for i in range(len(frogs)):
        if frogs[i]['pos'] > 0 and frogs[i]['id'] in remaining:
            result_frogs.append(frogs[i]['id'])

    # Output
    result_frogs = list(set(result_frogs[:]))
    result_frogs.sort()

    output = str(len(result_frogs)) + '\n'
    if result_frogs:
        output += ' '.join(map(str, sorted(result_frogs))) + ' '
    else:
        output += '\n'

    return output


